<script setup lang="ts">
import { ref, computed } from 'vue'
import { useFitness, DEFAULT_EXERCISE_IMAGE } from './store'
import ExerciseImage from './ExerciseImage.vue'
import { clone, newSet, type FitnessItem, type Exercise } from '../../../shared/fitness'
import AppIcon from '../components/AppIcon.vue'
const props=defineProps<{items:FitnessItem[];actual?:boolean}>(),fs=useFitness(),query=ref(''),expanded=ref(props.actual?0:-1),dragging=ref(-1),advanced=ref(false),picker=ref(false),replaceIndex=ref(-1),custom=ref(false),customName=ref(''),customMuscles=ref(''),customImage=ref('')
const results=computed(()=>fs.availableExercises.filter(e=>(e.name+e.alias+e.part).toLowerCase().includes(query.value.toLowerCase())).slice(0,25))
function add(id:string):void{if(replaceIndex.value>=0)props.items[replaceIndex.value]=fs.item(id);else props.items.push(fs.item(id));replaceIndex.value=-1;query.value='';picker.value=false}
function resize(item:FitnessItem,count:number):void{while(item.sets.length<count)item.sets.push(clone(item.sets[0]||newSet()));item.sets.splice(count)}
function drop(index:number):void{if(dragging.value<0)return;const [item]=props.items.splice(dragging.value,1);props.items.splice(index,0,item);dragging.value=-1}
function upload(event:Event):void{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>customImage.value=String(reader.result);reader.readAsDataURL(file)}
async function addCustom():Promise<void>{if(!customName.value.trim())return;const e:Exercise={id:crypto.randomUUID(),name:customName.value,alias:'',part:'自定义',muscles:customMuscles.value.split('、').filter(Boolean),secondary:[],equipment:'其他',measure:'weight',description:customMuscles.value?'主要锻炼：'+customMuscles.value+'。':'',notes:'',image:customImage.value||DEFAULT_EXERCISE_IMAGE,images:[customImage.value||DEFAULT_EXERCISE_IMAGE],favorite:false,tags:[],artworkStatus:'ready'};fs.editExercise(e);await fs.save();props.items.push(fs.item(e.id));custom.value=false;customName.value='';customImage.value=''}
</script>
<template><div class="fit-item-editor" :class="{'is-actual':actual}">
 <div v-if="!actual" class="fit-table-head"><span>#</span><span>动作</span><span>组数</span><span>每组次数</span><span>参考重量</span><span>组间休息</span><span>更多</span></div>
 <div v-for="(item,i) in items" :key="i" class="fit-edit-item" draggable="true" @dragstart="dragging=i" @dragover.prevent @drop.prevent="drop(i)">
  <template v-if="!actual"><div class="fit-item-summary"><span class="fit-grip">⠿</span><button type="button" class="fit-exercise-name" @click="expanded=expanded===i?-1:i"><ExerciseImage :image="fs.exercise(item.exerciseId)?.image" :alt="fs.exercise(item.exerciseId)?.name"/><strong>{{ fs.exercise(item.exerciseId)?.name || '已删除动作' }}</strong></button><input type="number" min="1" :value="item.sets.length" aria-label="组数" @change="resize(item,Number(($event.target as HTMLInputElement).value))"/><input v-if="fs.exercise(item.exerciseId)?.measure==='weight'" type="number" min="0" v-model.number="item.sets[0].reps" aria-label="每组次数" @change="item.sets.forEach(s=>s.reps=item.sets[0].reps)"/><span v-else>—</span><div class="fit-unit-input"><input v-if="fs.exercise(item.exerciseId)?.measure==='weight'" v-model.number="item.sets[0].weight" type="number" min="0" aria-label="参考重量" @change="item.sets.forEach(s=>s.weight=item.sets[0].weight)"/><input v-else-if="fs.exercise(item.exerciseId)?.measure==='time'" v-model.number="item.sets[0].duration" type="number" min="0" aria-label="时长" @change="item.sets.forEach(s=>s.duration=item.sets[0].duration)"/><input v-else v-model.number="item.sets[0].distance" type="number" min="0" aria-label="距离" @change="item.sets.forEach(s=>s.distance=item.sets[0].distance)"/><span>{{ fs.exercise(item.exerciseId)?.measure==='weight'?'kg':fs.exercise(item.exerciseId)?.measure==='time'?'秒':'米' }}</span></div><div class="fit-unit-input"><input type="number" min="0" v-model.number="item.rest" aria-label="组间休息"/><span>秒</span></div><div class="fit-item-more"><button type="button" class="fit-button" @click="replaceIndex=i;picker=true">替换</button><button type="button" class="fit-icon" aria-label="移除动作" @click="items.splice(i,1)"><AppIcon name="delete" :size="15"/></button></div></div></template>
  <button v-else type="button" class="fit-actual-summary" @click="expanded=expanded===i?-1:i"><span>{{ String(i+1).padStart(2,'0') }}</span><ExerciseImage :image="fs.exercise(item.exerciseId)?.image" :alt="fs.exercise(item.exerciseId)?.name"/><strong>{{ fs.exercise(item.exerciseId)?.name || '已删除动作' }}</strong><small v-if="expanded!==i">{{ item.sets.length }} 组 × {{ item.sets[0]?.reps??'—' }} 次　{{ item.sets[0]?.weight??'—' }} kg</small><span>{{ expanded===i?'⌃':'›' }}</span></button>
  <div v-if="expanded===i" class="fit-set-editor"><div class="fit-set-table-header"><span>组</span><span>{{ fs.exercise(item.exerciseId)?.measure==='weight'?'实际重量 kg':fs.exercise(item.exerciseId)?.measure==='time'?'实际时长 秒':'实际距离 米' }}</span><span>实际次数</span><span>备注</span><span></span></div><div v-for="(set,j) in item.sets" :key="j" class="fit-set-row"><span>{{ j+1 }}</span><input v-if="fs.exercise(item.exerciseId)?.measure==='weight'" v-model.number="set.weight" type="number" min="0" aria-label="实际重量"/><input v-else-if="fs.exercise(item.exerciseId)?.measure==='time'" v-model.number="set.duration" type="number" min="0" aria-label="实际时长"/><input v-else v-model.number="set.distance" type="number" min="0" aria-label="实际距离"/><input v-model.number="set.reps" type="number" min="0" aria-label="实际次数"/><input v-model="item.notes" placeholder="—" aria-label="备注"/><button type="button" class="fit-icon" :disabled="item.sets.length===1" @click="item.sets.splice(j,1)">×</button></div><button type="button" class="fit-button" @click="item.sets.push(newSet())">＋ 添加一组</button></div>
 </div>
 <div class="fit-item-add-actions"><button type="button" class="fit-button" @click="replaceIndex=-1;picker=!picker"><AppIcon name="plus" :size="17"/>从动作库添加</button><button type="button" class="fit-button" @click="custom=!custom"><AppIcon name="plus" :size="17"/>自定义动作</button></div>
 <div class="fit-add-exercise" v-if="picker"><input v-model="query" placeholder="搜索动作名称或部位"/><div class="fit-picker"><button type="button" v-for="e in results" @click="add(e.id)">{{ e.name }}<small>{{ e.part }} · {{ e.equipment }}</small></button><p v-if="!results.length">没有找到相关动作。</p></div></div>
 <div v-if="custom" class="fit-inline-custom"><label>中文名称<input v-model="customName"/></label><label>主要肌肉<input v-model="customMuscles" placeholder="用顿号分隔"/></label><label class="fit-upload">上传图片（选填）<input type="file" accept="image/*" @change="upload"/></label><small class="fit-muted">未上传时自动使用默认卡通图</small><button type="button" class="fit-primary" :disabled="!customName.trim()" @click="addCustom">添加动作</button></div>
 <button v-if="!actual" type="button" class="fit-advanced-toggle" @click="advanced=!advanced">{{ advanced?'⌃':'⌄' }}　高级设置：逐组目标、超级组、备注（可选）</button><div v-if="advanced"><p class="fit-muted">点击动作名称展开逐组编辑；相同分组名称的动作组成超级组。</p><label v-for="item in items" class="fit-label">{{ fs.exercise(item.exerciseId)?.name || '已删除动作' }}<input v-model="item.group" placeholder="超级组名称（可选）"/></label></div>
</div></template>
